# test/suites.map: which suites a changed file can break. Read by test/select.sh (and so by
# `test/all.sh --tier quick`). One rule per line:  <pattern>  <suite or @group or ALL> ...
#
# - Patterns are shell patterns matched against the path from the repository root; "*" also
#   matches "/". EVERY rule that matches a file counts: the suites are added up.
# - A changed file that no rule matches selects ALL (unknown means: run everything).
# - ALL = every suite of the full tier. Groups are defined with "@name = ...".
# - This map is a shortcut for the quick tier only. The full tier never reads it. When a suite
#   starts using another part of the tree, add the rule here; when in doubt, write ALL.

@local   = lint ui-test go install-test
@alerts  = e2e-alerts e2e-alerts-timer e2e-alerts-daemon
@faults  = e2e-faults-q1 e2e-faults-q2 e2e-faults-q3 e2e-faults-q4 e2e-matrix-quick

# ---- the core: everything depends on it
bin/*                    ALL
lib/common.sh            ALL
lib/deploy.sh            ALL
lib/build.sh             ALL
lib/native.js            ALL
lib/args.sh              ALL
server/tando-agent       ALL
server/tando-install-recover  ALL
srv/internal/*           ALL
srv/cmd/*                ALL
srv/go.mod               ALL
srv/daemon/*             ALL
VERSION                  ALL
test/lib.sh              ALL
test/all.sh              ALL
test/select.sh           ALL
test/suites.map          ALL
test/server/*            ALL

# ---- laptop side
lib/ui.sh                lint ui-test e2e-cli e2e-ease e2e-top e2e-status
lib/views.sh             lint ui-test e2e-cli e2e-status e2e-data e2e e2e-alerts e2e-host e2e-logs
