lib/cmd-health.sh        lint ui-test e2e-cli @alerts
lib/cmd-audit.sh         lint ui-test e2e-cli e2e-logs e2e-ci
lib/cmd-cheat.sh         lint ui-test e2e-cli e2e-ease
lib/cmd-ci.sh            lint ui-test e2e-cli e2e-ci e2e-sec2
lib/cmd-domain.sh        lint ui-test e2e-cli e2e-ease e2e
lib/cmd-errors.sh        lint ui-test e2e-cli e2e-logs
lib/cmd-go.sh            lint ui-test e2e-cli e2e-ease e2e-bootstrap e2e-trial
lib/cmd-link.sh          lint ui-test e2e-cli e2e-ease
lib/cmd-logx.sh          lint ui-test e2e-cli e2e-logs
lib/cmd-next.sh          lint ui-test e2e-cli e2e-ease
lib/cmd-open.sh          lint ui-test e2e-cli e2e-ease
