lib/cmd-top.sh           lint ui-test e2e-cli e2e-top
lib/hostcare.sh          lint ui-test e2e-cli e2e-host
lib/offsite.sh           lint ui-test e2e-cli e2e-offsite e2e-data
lib/studio.sh            lint ui-test e2e-cli e2e-studio

# ---- server side
server/tando-adopt       lint ui-test e2e-ci e2e-status e2e-adopt
server/legacy/*          lint install-test e2e-status @alerts
srv/watch/*              go @alerts e2e-status e2e-host e2e-faults-q4
srv/logs/*               go e2e-logs e2e e2e-ci @alerts
srv/offsite/*            go e2e-offsite e2e-data
srv/status/*             go e2e-status e2e-top e2e-cli
srv/metrics/*            go e2e-status e2e-top e2e-sec2 @alerts
srv/gate/*               go e2e-ci e2e-sec2
srv/hostcare/*           go e2e-host @alerts
srv/studio/*             go e2e-studio
srv/tools/*              go
srv/README.md            lint

# ---- packaging, examples, docs
