docs/*                   lint ui-test e2e-cli install-test
*.md                     lint ui-test e2e-cli install-test
LICENSE                  lint
.gitignore               lint
.github/*                lint
bench/*                  lint

# ---- the tests themselves
test/lint*               lint
test/go.sh               go
test/ui-test*            ui-test lint
test/native-test.sh      ui-test lint
test/pty-run.sh          ui-test e2e-top lint
test/top-pty.py          e2e-top
test/install-test.sh     install-test lint
test/secret-scan-test.sh lint
test/check.sh            lint
