test/e2e-matrix*         e2e-matrix-quick e2e-matrix-weekly lint
test/faults/*            @faults e2e-matrix-quick e2e-matrix-weekly lint
test/sec2/*              e2e-sec2 lint
test/sec3/*              e2e-sec2 lint
test/load/*              lint
test/race/*              lint
